// TH16 v1.00a type 7 = TH16_RING_BALL2 (approved reuse of the identical TH18 slot).
// Only the constant this card needs is copied from transcribe/th16/touhou-bullets.ecl.
const TH16_RING_BALL2: int = 464;

// th16_s5_w03 — TH16 v1.00a Stage 5 / MainSub02 (st05.ecl.txt:1094-1176).
// Four phantom formations; dependencies Phantom01R/Phantom01/Phantom01_at/Phantom01_at2
// (st05.ecl.txt:1366-1484). Source frames and target frames relate as described in report.md.

const TIME_LIMIT: int = 1124;
const OPENING_BUFFER: int = 120;

// Phantom01_at (E/N): WAIT(60), then ACCEL type4 a=200 r=0.02 with angle sentinel -999999,
// i.e. acceleration along the bullet's current direction (90deg, downward).
// The birth ANIM record (type2 a=1) is omitted per policy; only its -4*velocity spawn offset
// is kept at fire time.
xformdef DOWN_ACCEL(accel: fx, frames: int) {
    @60 add_speed(0fx);
    set_gravity(0fx, accel);
    wait(frames);
    set_gravity(0fx, 0fx);
}

// Phantom01_at2 (H/L): WAIT(60), then STEP type16 a=1 b=1 c=1 d=0 s=0 -> one tick at the old
// speed, then speed=0 and re-aim at the player at the segment boundary; ACCEL then accelerates
// along that aimed direction (angle sentinel keeps the current angle).
xformdef STEP_AIM(accel: fx, frames: int) {
    @60 add_speed(0fx);
    wait(1);                      // STEP's single 1-frame segment at the old speed
    set_speed(0fx);
    set_angle(at_effect(aim_player()));
    set_gravity(at_effect(accel * cos(aim_player())), at_effect(accel * sin(aim_player())));
    wait(frames);
    set_gravity(0fx, 0fx);
}

// Phantom01_at / Phantom01_at2: etSprite(0,7,2), etAim(0,1) fixed fan of 1 way (=90deg),
// etCount(0,1,1), etSpeed(0,0.1,1) with one layer -> 0.1 px/frame. The loop is the source's
// 1000 iterations of `wait(10); etOn(0);`.
async sub phantom_shooter() {
    var rank: int = global(GVAR_RANK);
    for i in 0..1000 {
        wait(10);
        if rank >= RANK_HARD {
            if rank == RANK_LUNATIC {
                _ = fire(TH16_RING_BALL2, 2, $self_x, $self_y - 0.4fx, 0.1fx, 90deg, STEP_AIM(0.04fx, 100), none);
            } else {
                _ = fire(TH16_RING_BALL2, 2, $self_x, $self_y - 0.4fx, 0.1fx, 90deg, STEP_AIM(0.02fx, 200), none);
            }
        } else {
            _ = fire(TH16_RING_BALL2, 2, $self_x, $self_y - 0.4fx, 0.1fx, 90deg, DOWN_ACCEL(0.02fx, 200), none);
        }
    }
}

// Phantom01R/Phantom01: boxes, ABS polar drift (angle toward (0,-300), negative speed 0.5 -> 1.5
// with mode3 quartic-in) plus the REL ellipse wobble (r=10, omega 2deg/frame, ratio 0, axis
// frozen at the ABS angle when the ellipse was set).
async sub phantom_main() {
    set_invuln(65535);
    set_hurtbox(14fx);            // setHurtbox(28,28): circular branch, first value * 0.5
    set_hitbox(8fx);              // setHitbox(16,16): first value * 0.5
    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var beta: angle = atan2(-300fx - y0, 0fx - x0);  // getAngle(FINAL -> (0,-300)), also ellipse axis
    var d: fx = 0fx;              // accumulated ABS distance; source speed is negative
    var theta: angle = 0deg;      // ellipse phase from inherited F0 = 0
    var k: int = 0;
    spawn phantom_shooter();      // Phantom01_at / Phantom01_at2 async
    wait(1);                      // source config frame has no movement tick yet
    loop {
        k = k + 1;
        var spd: fx = -1.5fx;
        if k <= 120 {
            var u: fx = (k as fx) / 120fx;
            spd = -0.5fx - u*u*u*u;   // moveVelTime(120, mode3): quartic IN from -0.5 to -1.5
        }
        d = d + spd;
        theta = theta + 2deg;     // moveEllipseRel omega = 0.034906585 rad/frame
        var mag: fx = 10fx * sin(theta - beta);       // ratio=0: fixed-axis sine offset
        var px: fx = x0 + d*cos(beta) - mag*sin(beta);
        var py: fx = y0 + d*sin(beta) + mag*cos(beta);
        move_to(0, px, py, EASE_LINEAR);
        wait(1);
    }
}

// One MainSub02 formation: enmCreate is relative to the stage FINAL (0,0); the count and
// spacing/extra-wait values are resolved by the caller from diffI.
sub spawn_wave(start: fx, stepx: fx, count: int) {
    var a: fx = start;
    for i in 0..count {
        _ = spawn_enemy(a, -16fx, 350, 0, 1000, 0, phantom_main);
        a = a + stepx;
        wait(10);
    }
}

// MainSub02 body: 4 formations alternating +/- x, count 7/11, spacing 48/32, inter-wave 120/100.
async sub pattern() {
    wait(OPENING_BUFFER);
    var count: int = 11;          // diffI($B/$C/$D/$E, 7, 11, 11, 11)
    var stepx: fx = 32fx;         // +32; Easy additionally +16
    var gap: int = 100;           // E=120, N/H/L=100
    if global(GVAR_RANK) == RANK_EASY { count = 7; stepx = 48fx; gap = 120; }
    spawn_wave(-160fx, stepx, count);
    wait(gap);
    spawn_wave(160fx, 0fx - stepx, count);
    wait(gap);
    spawn_wave(-160fx, stepx, count);
    wait(gap);
    spawn_wave(160fx, 0fx - stepx, count);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
